/**
 * Structured logging for Neatlogs traces.
 *
 * The log() function captures timestamped steps within a trace,
 * emitting OTel LogRecords that are associated with the active span.
 */

import { AsyncLocalStorage } from 'node:async_hooks';
import { getLogger } from './logger.js';
import {
  getActiveNeatlogsSpan,
  getNeatlogsActiveContext,
} from './provider.js';
import { getActiveClient } from './active-client.js';

const logger = getLogger();

// Entry points are bundled independently, so init() and log() can execute from
// different copies of this module in the same process. Keep the logger state on
// globalThis so every Neatlogs bundle resolves the logger configured by init().
const LOG_RUNTIME_STATE_KEY = Symbol.for('neatlogs.log_runtime_state');
interface LogRuntimeState {
  otelLogger: any | null;
  debugMode: boolean;
}
type NeatlogsGlobal = typeof globalThis & {
  [LOG_RUNTIME_STATE_KEY]?: LogRuntimeState;
};
const neatlogsGlobal = globalThis as NeatlogsGlobal;
const logRuntimeState =
  neatlogsGlobal[LOG_RUNTIME_STATE_KEY] ??
  (neatlogsGlobal[LOG_RUNTIME_STATE_KEY] = {
    otelLogger: null,
    debugMode: false,
  });
const stdoutCaptureContext = new AsyncLocalStorage<boolean>();
let stdoutCaptureDepth = 0;
let originalConsoleLog: typeof console.log | null = null;
let captureConsoleLog: typeof console.log | null = null;

function resolveOtelLogger(): any | null {
  const client = getActiveClient();
  // An active Client owns the whole context. `null` means logging is disabled
  // for that Client; it must never fall through to the process-global project.
  return client ? client.getLogger() : logRuntimeState.otelLogger;
}

/**
 * Set the OTel logger instance. Called by init().
 * @internal
 */
export function _setOtelLogger(otelLogger: any, debug: boolean): void {
  logRuntimeState.otelLogger = otelLogger;
  logRuntimeState.debugMode = debug;
}

/**
 * Capture a timestamped log step within the current trace.
 *
 * @param msgTemplate - Message template with {key} placeholders
 * @param options - Optional key-value pairs for template rendering and attributes
 *
 * @example
 * ```typescript
 * log('Processing query: {query}', { query: 'What is TypeScript?', level: 'info' });
 * ```
 */
export function log(
  msgTemplate: string,
  options?: Record<string, any>,
): void {
  const { level = 'info', ...variables } = options ?? {};

  // Render template
  let rendered = msgTemplate;
  for (const [key, value] of Object.entries(variables)) {
    rendered = rendered.replace(new RegExp(`\\{${key}\\}`, 'g'), String(value));
  }

  // Echo to console in debug mode
  if (logRuntimeState.debugMode) {
    console.log(`[neatlogs:log] ${rendered}`);
  }

  // Emit OTel LogRecord if logger is available
  const otelLogger = resolveOtelLogger();
  if (otelLogger) {
    // Correlate to the active NEATLOGS span, not the global active span: in
    // isolated mode the latter is the foreign co-tenant's (Datadog/Braintrust)
    // span, which would either mis-correlate the log or attach a foreign context.
    const activeSpan = getActiveNeatlogsSpan();
    const activeContext = activeSpan ? getNeatlogsActiveContext() : undefined;

    const attributes: Record<string, any> = {
      'log.template': msgTemplate,
      'log.level': level,
    };

    // Add template variables as log.{key} attributes
    for (const [key, value] of Object.entries(variables)) {
      attributes[`log.${key}`] = String(value);
    }

    try {
      otelLogger.emit({
        body: rendered,
        attributes,
        // The OTel Logs API accepts a Context, not a raw SpanContext. Passing
        // `spanContext` is silently ignored by sdk-logs, producing a log with
        // no trace id that the Neatlogs ingest route correctly discards.
        ...(activeContext ? { context: activeContext } : {}),
      });
    } catch (err) {
      logger.warn(`Failed to emit log record: ${err}`);
    }
  }
}

/**
 * Capture stdout (console.log) within a callback and route to OTel logger.
 *
 * @param fn - The function to execute while capturing stdout
 * @returns The return value of fn
 */
export async function captureStdout<T>(fn: () => T | Promise<T>): Promise<T> {
  if (!resolveOtelLogger()) {
    return fn();
  }

  if (stdoutCaptureDepth === 0) {
    originalConsoleLog = console.log;
    captureConsoleLog = (...args: any[]) => {
      originalConsoleLog?.apply(console, args);
      if (!stdoutCaptureContext.getStore()) return;
      const otelLogger = resolveOtelLogger();
      if (!otelLogger) return;
      const activeSpan = getActiveNeatlogsSpan();
      const activeContext = activeSpan ? getNeatlogsActiveContext() : undefined;
      const message = args
        .map((a) => (typeof a === 'string' ? a : JSON.stringify(a)))
        .join(' ');
      try {
        otelLogger.emit({
          body: message,
          attributes: {
            'log.source': 'stdout',
            'log.level': 'info',
          },
          ...(activeContext ? { context: activeContext } : {}),
        });
      } catch {
        // Ignore errors in log capture
      }
    };
    console.log = captureConsoleLog;
  }
  stdoutCaptureDepth += 1;

  try {
    return await stdoutCaptureContext.run(true, fn);
  } finally {
    stdoutCaptureDepth -= 1;
    if (stdoutCaptureDepth === 0) {
      if (captureConsoleLog && console.log === captureConsoleLog && originalConsoleLog) {
        console.log = originalConsoleLog;
      }
      originalConsoleLog = null;
      captureConsoleLog = null;
    }
  }
}
